-- CUSTOM POSTGRESQL EXTENSIONS & INTEGRITY CONSTRAINTS
-- =============================================================================

-- 1. Active Seat Allocation Partial Unique Index
-- Guarantees ZERO double-bookings at the database engine level.
-- Only active states occupy the seat (PENDING_PAYMENT, CONFIRMED, CHECKED_IN).
-- CANCELLED and REFUNDED_RELEASED release the seat back to inventory.
-- REFUNDED_RESTRICTED (customer disputes, damaged seats, post-show refunds) keeps
-- the seat blocked so it cannot be resold.
CREATE UNIQUE INDEX "uq_active_showtime_seat"
ON "tickets" ("showtime_id", "seat_id")
WHERE "status" IN ('PENDING_PAYMENT', 'CONFIRMED', 'CHECKED_IN', 'REFUNDED_RESTRICTED');

-- 2. Booking Capacity Invariant
-- Enforces that a customer order contains between 1 and 8 seats per transaction
ALTER TABLE "bookings"
ADD CONSTRAINT "chk_booking_seat_count"
CHECK ("seat_count" >= 1 AND "seat_count" <= 8);

-- 3. Cross-Table Auditorium Consistency
-- Ensures that a Ticket's showtime and allocated physical seat belong to the exact same auditorium.
CREATE OR REPLACE FUNCTION verify_ticket_auditorium()
RETURNS TRIGGER AS $$
DECLARE
    v_showtime_auditorium_id TEXT;
    v_seat_auditorium_id TEXT;
BEGIN
    SELECT "auditorium_id" INTO v_showtime_auditorium_id
    FROM "showtimes" WHERE "id" = NEW."showtime_id";

    SELECT "auditorium_id" INTO v_seat_auditorium_id
    FROM "seats" WHERE "id" = NEW."seat_id";

    IF v_showtime_auditorium_id IS NULL OR v_seat_auditorium_id IS NULL THEN
        RAISE EXCEPTION 'Showtime % or Seat % does not exist', NEW."showtime_id", NEW."seat_id";
    END IF;

    IF v_showtime_auditorium_id <> v_seat_auditorium_id THEN
        RAISE EXCEPTION 'Auditorium mismatch: Showtime % is in auditorium % but Seat % is in auditorium %',
            NEW."showtime_id", v_showtime_auditorium_id, NEW."seat_id", v_seat_auditorium_id;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "trg_verify_ticket_auditorium"
BEFORE INSERT OR UPDATE ON "tickets"
FOR EACH ROW
EXECUTE FUNCTION verify_ticket_auditorium();

-- Prevent altering auditorium_id on a showtime if tickets have already been issued
CREATE OR REPLACE FUNCTION verify_showtime_auditorium_immutable()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD."auditorium_id" <> NEW."auditorium_id" THEN
        IF EXISTS (SELECT 1 FROM "tickets" WHERE "showtime_id" = OLD."id") THEN
            RAISE EXCEPTION 'Cannot alter auditorium_id on showtime %: tickets have already been issued for this screening', OLD."id";
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "trg_verify_showtime_auditorium_immutable"
BEFORE UPDATE OF "auditorium_id" ON "showtimes"
FOR EACH ROW
EXECUTE FUNCTION verify_showtime_auditorium_immutable();

-- Prevent altering auditorium_id on a physical seat if tickets exist
CREATE OR REPLACE FUNCTION verify_seat_auditorium_immutable()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD."auditorium_id" <> NEW."auditorium_id" THEN
        IF EXISTS (SELECT 1 FROM "tickets" WHERE "seat_id" = OLD."id") THEN
            RAISE EXCEPTION 'Cannot alter auditorium_id on physical seat %: tickets exist for this seat', OLD."id";
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "trg_verify_seat_auditorium_immutable"
BEFORE UPDATE OF "auditorium_id" ON "seats"
FOR EACH ROW
EXECUTE FUNCTION verify_seat_auditorium_immutable();

-- 4. Showtime Consistency: Ticket showtime must match parent Booking showtime
CREATE OR REPLACE FUNCTION verify_ticket_booking_showtime()
RETURNS TRIGGER AS $$
DECLARE
    v_booking_showtime_id TEXT;
BEGIN
    SELECT "showtime_id" INTO v_booking_showtime_id
    FROM "bookings" WHERE "id" = NEW."booking_id";

    IF v_booking_showtime_id IS NULL THEN
        RAISE EXCEPTION 'Parent booking % does not exist for ticket %', NEW."booking_id", NEW."id";
    END IF;

    IF v_booking_showtime_id <> NEW."showtime_id" THEN
        RAISE EXCEPTION 'Showtime mismatch: Ticket % showtime (%) does not match parent booking % showtime (%)',
            NEW."id", NEW."showtime_id", NEW."booking_id", v_booking_showtime_id;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "trg_verify_ticket_booking_showtime"
BEFORE INSERT OR UPDATE ON "tickets"
FOR EACH ROW
EXECUTE FUNCTION verify_ticket_booking_showtime();

-- Prevent altering showtime_id on a booking if tickets are already allocated
CREATE OR REPLACE FUNCTION verify_booking_showtime_immutable()
RETURNS TRIGGER AS $$
BEGIN
    IF OLD."showtime_id" <> NEW."showtime_id" THEN
        IF EXISTS (SELECT 1 FROM "tickets" WHERE "booking_id" = OLD."id") THEN
            RAISE EXCEPTION 'Cannot alter showtime_id on booking %: tickets have already been allocated', OLD."id";
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER "trg_verify_booking_showtime_immutable"
BEFORE UPDATE OF "showtime_id" ON "bookings"
FOR EACH ROW
EXECUTE FUNCTION verify_booking_showtime_immutable();

